parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "reply": {
      "type": "string",
      "description": "The text the customer will receive in Telegram, written in Bulgarian. No markdown, no internal notes, at most 120 words, signed „Екип Сервиз“."
    },
    "sources": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "The verbatim quotes from the knowledge base the answer rests on, including the chunk code (e.g. PRO-03). If you did not use the base, return an empty array."
    }
  },
  "required": [
    "reply",
    "source"
  ]
}
